-- PokeSouq (pokesouq.myshopify.com) -- daily Shopify analytics backfill.
--
-- One row per calendar day from 2023-05-01 through 2026-09-14 (1233 rows),
-- covering the store's entire history (first order 2023-05-01).
-- Generated from Shopify analytics (ShopifyQL: FROM sales / FROM sessions,
-- TIMESERIES day) on 2026-09-14. Currency is AED.
--
-- Sources:
--   sales    -> orders, total_sales, average_order_value, new_customers, returning_customers
--   sessions -> sessions, conversion_rate
--
-- Notes:
--   * total_sales CAN LEGITIMATELY BE NEGATIVE on days dominated by refunds
--     (e.g. a refund posted on a day with no offsetting orders). Do not clamp to zero.
--   * NULL means Shopify returned no value for that metric on that day (an empty
--     average_order_value or conversion_rate). NULL is never substituted with 0,
--     and a reported 0 is a real zero, not a missing value.
--   * conversion_rate is a fraction (0.025 = 2.5%), not a percentage.
--   * average_order_value is Shopify's own figure and does not always equal
--     total_sales / orders (refunds, edits and cancellations are attributed
--     differently between the two metrics).
--
-- Re-runnable: every batch upserts on day.

-- rows 1-500 (2023-05-01 .. 2024-09-11)
ON CONFLICT (day) DO UPDATE SET
  sessions = excluded.sessions, orders = excluded.orders,
  new_customers = excluded.new_customers, returning_customers = excluded.returning_customers,
  total_sales = excluded.total_sales, average_order_value = excluded.average_order_value,
  conversion_rate = excluded.conversion_rate, captured_at = now();

-- rows 501-1000 (2024-09-12 .. 2026-01-24)
ON CONFLICT (day) DO UPDATE SET
  sessions = excluded.sessions, orders = excluded.orders,
  new_customers = excluded.new_customers, returning_customers = excluded.returning_customers,
  total_sales = excluded.total_sales, average_order_value = excluded.average_order_value,
  conversion_rate = excluded.conversion_rate, captured_at = now();

-- rows 1001-1233 (2026-01-25 .. 2026-09-14)
ON CONFLICT (day) DO UPDATE SET
  sessions = excluded.sessions, orders = excluded.orders,
  new_customers = excluded.new_customers, returning_customers = excluded.returning_customers,
  total_sales = excluded.total_sales, average_order_value = excluded.average_order_value,
  conversion_rate = excluded.conversion_rate, captured_at = now();

